@Component({
    selector: 'app-list-carga-masiva',
    imports: [
    TablaComponent,
    FormularioFlotanteComponent,
    EditarCargaMasivaComponent,
    FormsModule
],
    templateUrl: './list-carga-masiva.component.html',
    styleUrl: './list-carga-masiva.component.css'
})
export class ListCargaMasivaComponent {
  tabla = TABLA_DEF
  agregar_button = AGREGAR_BUTTON
  showEdit: boolean = false
  cargaMasivaEdit?: PagoCargaMasiva
  showDeleteForm: boolean = false
  advancedSearch = ADVANCED_FILTERS
  @ViewChild('tablaRef') tableRef: TablaComponent<PagoCargaMasiva> | undefined
  nota: string = ''
  constructor(
    public pagoMasivoController: PagoCargaMasivaService,
    public creditoController: CreditoService,
  ) { }

  onDelete(carga: PagoCargaMasiva) {
    this.nota = ''
    this.showDeleteForm = true
    this.cargaMasivaEdit = carga
    console.log('DELETE EVENT')
  }

  async deleteCargaMasiva() {
    if (!this.cargaMasivaEdit) return
    if (!this.tableRef) return
    await this.pagoMasivoController.switch(this.cargaMasivaEdit, { nota: this.nota })

    if (this.cargaMasivaEdit?.creditos_abonos?.creditos) {
      await this.creditoController.actualizarEstadoCuenta(this.cargaMasivaEdit.creditos_abonos?.creditos)
    }

    this.showDeleteForm = false
    this.cargaMasivaEdit = undefined
    this.tableRef.getData()
  }
}
