import { Component } from '@angular/core';
import { ExcelReaderService } from '../../../services/excel-reader.service';
import { UtilsService } from '../../../services/utils.service';
import { CurrencyPipe, DatePipe, NgClass } from '@angular/common';
import {
  CargaMasivaRevision,
  PagoCargaMasivaService,
} from '../../../controllers/pago.carga.masiva.service';
import { AutocompleteFieldComponent } from '../../../shared/generic-form/autocomplete-field/autocomplete-field.component';
import { PagoCargaMasiva } from '../../../models/pago.carga.masiva';
import { Router } from '@angular/router';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { PagoLayoutService } from '../../../controllers/pago.layout.service';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { PagoLayout } from '../../../models/pago.layout.model';
import { VersionComponent } from "../../../shared/version/version.component";

@Component({
  selector: 'app-abono-masivo',
  imports: [
    AutocompleteFieldComponent,
    DatePipe,
    CurrencyPipe,
    ScrollingModule,
    NgClass,
    VersionComponent
],
  templateUrl: './abono-masivo.component.html',
  styleUrl: './abono-masivo.component.css',
})
export class AbonoMasivoComponent {
  dataSource: any[] = [];
  keys = [
    'descripcion',
    'referencia_de_cliente',
    'tipo_de_trn',
    'fecha_valor',
    'importe_de_credito',
    'hora_de_cargo_o_abono',
    'fecha_del_apunte',
  ];
  dataRevisada?: CargaMasivaRevision;
  cargasMasivas: (PagoCargaMasiva & { coincidencia_escrita?: number })[] = [];
  creditos: Credito[] = [];
  extraDataAutoComplete: any = {
    conditionals: JSON.stringify([
      ['deleted_at', 'IS NULL', null],
      ['estado', '=', 'ACTIVO'],
      ['liberado_fecha', 'IS NOT NULL', null],
      ['folio_reestructura', 'IS NULL', null],
    ]),
  };

  file: File | null = null;

  stats = {
    procesados: 0,
    validos: 0,
    total: 0,
    manual: 0,
    exactos: 0,
    no_identificados: 0,
  };
  constructor(
    private excelReader: ExcelReaderService,
    public pagosMasivosController: PagoCargaMasivaService,
    public utils: UtilsService,
    private creditoController: CreditoService,
    private pagoLayoutController: PagoLayoutService,
    private router: Router,
    private dialog: VanillaDialogService,
  ) {}

  async onFileSelected(event: Event) {
    this.file = this.utils.fileFromInputEvent(event);
    if (this.file) {
      this.dataSource = await this.excelReader.readExcelAsJsonList(this.file);
      this.cleanFechas();
      const keys = Object.keys(this.dataSource[0]);
      this.dataSource = this.dataSource.filter((row) => {
        return !Object.values(row).every((value) => value === null);
      });
      console.log(this.dataSource);
    }
  }

  public referenciaFromCargaMasiva(carga: PagoCargaMasiva) {
    return this.creditos.find((c) => c.id == carga.credito_id)
      ?.referencia_bancaria;
  }

  private setStats() {
    this.stats.procesados =
      (this.dataRevisada?.correctos.exactos.length ?? 0) +
      (this.dataRevisada?.correctos.no_encontrados.length ?? 0) +
      (this.dataRevisada?.correctos.potenciales.length ?? 0);
    this.stats.total = this.dataSource.reduce(
      (acc, item) => acc + +(item.importe_de_credito ?? 0),
      0,
    );
    this.stats.manual = this.dataRevisada?.correctos.potenciales.length ?? 0;
    this.stats.exactos = this.dataRevisada?.correctos.exactos.length ?? 0;
    this.stats.no_identificados =
      this.dataRevisada?.correctos.no_encontrados.length ?? 0;
  }

  public async revisar() {
    if (await this.pagoLayoutController.yaSeSubioExcel(this.file!)) {
      this.dialog.show({
        title: 'Excel duplicado',
        body: 'El excel ya se ha subido anteriormente.',
        tipo: 'danger',
      });
      return;
    }

    this.dataRevisada = await this.pagosMasivosController.revisar(
      this.dataSource,
    );
    this.dataRevisada.correctos.exactos.forEach(
      (r) => (r.coincidencia_escrita = 100),
    );
    this.setStats();
    const todos = [
      ...this.dataRevisada.correctos.potenciales,
      ...this.dataRevisada.correctos.exactos,
      ...this.dataRevisada.correctos.no_encontrados,
    ];
    todos.sort(
      (a, b) => (b.coincidencia_escrita ?? 0) - (a.coincidencia_escrita ?? 0),
    );
    this.cargasMasivas = [...todos];
  }

  async finalizarRevision() {
    const layout = await this.guardarFile();
    if (!layout) return;

    const data: PagoCargaMasiva[] = [
      ...this.dataRevisada!.correctos.exactos,
      ...this.dataRevisada!.correctos.potenciales,
      ...this.dataRevisada!.correctos.no_encontrados,
    ];

    data.forEach((p) => (p.pagos_layout_id = layout.id));

    console.log(data);

    const res = await this.pagosMasivosController.multipleNews(data);

    const creditos = data
      .filter((r) => !!r.credito_id)
      .map((r) => r.credito_id!);

    if (res) {
      await this.creditoController.actualizarEstadosCuentaMasiva(creditos);
      this.router.navigate(['/pagos/masiva/list']);
    }else{
      this.pagoLayoutController.switch(layout)
    }
  }

  removerAsignacion(item: PagoCargaMasiva) {
    console.log(item);
    // buscar el item en this.cargasMasivas y poner credito_id en null
    const index = this.cargasMasivas.findIndex((c) => c == item);
    if (index >= 0) {
      this.cargasMasivas[index].credito_id = null;
      this.cargasMasivas[index].coincidencia_escrita = 0;
      this.cargasMasivas[index].aplicado = 'NO';
      this.dataRevisada?.correctos.no_encontrados.push(
        this.cargasMasivas[index],
      );
      this.dataRevisada!.correctos.potenciales =
        this.dataRevisada!.correctos.potenciales.filter((c) => c != item);
      this.dataRevisada!.correctos.exactos =
        this.dataRevisada!.correctos.exactos.filter((c) => c != item);
      this.setStats();
    }
  }

  private async guardarFile() {
    if (!this.dataRevisada || !this.file) return;
    const todos = [
      ...this.dataRevisada.correctos.potenciales,
      ...this.dataRevisada.correctos.exactos,
      ...this.dataRevisada.correctos.no_encontrados,
    ];
    const data: Partial<PagoLayout> = {
      numero_movimientos: todos.length,
      monto_total: todos.reduce(
        (acc, item) => acc + +item.importe_de_credito,
        0,
      ),
      hash_archivo: await this.utils.calculateFileHash(this.file!),
      nombre_archivo_registro: this.file!.name,
      status_aplicacion: 'APLICADO',
    };
    return await this.pagoLayoutController.new({
      data: data,
      file: this.file,
    });
  }

  private cleanFechas() {
    if (this.dataSource.length == 0) return;
    const keys = Object.keys(this.dataSource[0]);
    this.dataSource.forEach((row) => {
      keys.forEach((key) => {
        if (this.isDateTimeOrDateFormat(row[key])) {
          row[key] = this.convertToISOString(row[key]);
        }
      });
    });
  }

  /**
   * Verifica si un valor en formato string cumple con el formato de fecha
   * "dd/MM/yyyyYY" o "dd/MM/yyyyYY HH:mm".
   *
   * @param value - Cadena a validar.
   * @returns `true` si el valor cumple con el formato, de lo contrario, `false`.
   */
  private isDateTimeOrDateFormat(value: string): boolean {
    const dateTimeRegex =
      /^([0-2][0-9]|3[0-1])\/(0[1-9]|1[0-2])\/(\d{4})( ([0-1][0-9]|2[0-3]):([0-5][0-9]))?$/;
    return dateTimeRegex.test(value);
  }

  /**
   * Convierte una fecha en formato "dd/MM/yyyyYY" o "dd/MM/yyyyYY HH:mm" a una cadena ISO 8601.
   *
   * @param value - Cadena en formato de fecha a convertir.
   * @returns La fecha en formato ISO si es válida, de lo contrario, `null`.
   */
  private convertToISOString(value: string): string | null {
    if (!this.isDateTimeOrDateFormat(value)) {
      return null; // Retorna null si no cumple con el formato esperado
    }

    const [datePart, timePart] = value.split(' ');
    const [day, month, year] = datePart.split('/').map(Number);
    const [hours, minutes] = timePart
      ? timePart.split(':').map(Number)
      : [0, 0]; // Si no hay hora, usa 00:00

    const date = new Date(year, month - 1, day, hours, minutes);

    return isNaN(date.getTime()) ? null : date.toISOString(); // Retorna null si la fecha no es válida
  }
}
